import pytest

import client
import worker


def test_default_returns_exact_envelope():
    assert client.timeout_result() == {'ok': False, 'reason': 'timeout'}


def test_none_returns_exact_envelope():
    assert client.timeout_result(retry_after=None) == {
        'ok': False, 'reason': 'timeout'}


def test_zero_adds_retry_after():
    assert client.timeout_result(retry_after=0) == {
        'ok': False, 'reason': 'timeout', 'retry_after': 0}


def test_positive_adds_retry_after():
    assert client.timeout_result(retry_after=5) == {
        'ok': False, 'reason': 'timeout', 'retry_after': 5}


@pytest.mark.parametrize('value', [True, False, 1.5, '3', [1], object()])
def test_nonint_retry_after_raises_type_error(value):
    with pytest.raises(TypeError):
        client.timeout_result(retry_after=value)


def test_negative_retry_after_raises_value_error():
    with pytest.raises(ValueError):
        client.timeout_result(retry_after=-1)


def test_timeout_result_retry_after_is_keyword_only():
    with pytest.raises(TypeError):
        client.timeout_result(3)


def test_should_retry_retry_after_is_keyword_only():
    with pytest.raises(TypeError):
        worker.should_retry(3)


def test_should_retry_forwards_retry_after(monkeypatch):
    seen = {}

    def fake(*, retry_after=None):
        seen['retry_after'] = retry_after
        return {'ok': False, 'reason': 'timeout'}

    monkeypatch.setattr(worker, 'timeout_result', fake)
    assert worker.should_retry(retry_after=7) is True
    assert seen['retry_after'] == 7


def test_should_retry_forwarded_default_is_none(monkeypatch):
    seen = {}

    def fake(*, retry_after=None):
        seen['retry_after'] = retry_after
        return {'ok': False, 'reason': 'timeout'}

    monkeypatch.setattr(worker, 'timeout_result', fake)
    assert worker.should_retry() is True
    assert seen['retry_after'] is None


def test_should_retry_ok_false_branch(monkeypatch):
    monkeypatch.setattr(
        worker, 'timeout_result',
        lambda *, retry_after=None: {'ok': False, 'reason': 'timeout'})
    assert worker.should_retry() is True


def test_should_retry_ok_true_branch(monkeypatch):
    monkeypatch.setattr(
        worker, 'timeout_result',
        lambda *, retry_after=None: {'ok': True, 'reason': 'timeout'})
    assert worker.should_retry() is False

